export async function render(value, options, api) {
  const { mode, onChange, label, indent = 0, fields } = options;
  const obj = value || {};
  const isEditable = mode === 'editable' && onChange;

  const wrapper = api.createElement('div', { class: 'field-object' });
  wrapper.style.cssText = 'display: flex; flex-direction: column; gap: 8px;';

  if (label) {
    const labelEl = api.createElement('div');
    labelEl.textContent = label;
    labelEl.style.cssText = 'font-weight: 600; font-size: 0.875rem; color: var(--color-text); margin-bottom: 4px;';
    wrapper.appendChild(labelEl);
  }

  const propsContainer = api.createElement('div');
  propsContainer.style.cssText = 'display: flex; flex-direction: column; gap: 12px; padding-left: ' + (indent > 0 ? '16px' : '0') + '; border-left: ' + (indent > 0 ? '2px solid var(--color-border)' : 'none') + ';';

  const updateProp = (key, newValue) => {
    // Read live object value if available — stale obj causes earlier field edits to
    // be lost when a second field is edited (e.g. instrument-id wiped by units edit).
    const current = options.getCurrentValue ? (options.getCurrentValue() || obj) : obj;
    const updated = { ...current, [key]: newValue };
    onChange(updated);
  };

  const deleteProp = (key) => {
    const updated = { ...obj };
    delete updated[key];
    onChange(updated);
  };

  const renameProp = (oldKey, newKey) => {
    if (oldKey === newKey || !newKey) return;
    const updated = {};
    for (const k of Object.keys(obj)) {
      if (k === oldKey) {
        updated[newKey] = obj[oldKey];
      } else {
        updated[k] = obj[k];
      }
    }
    onChange(updated);
  };

  const renderInternalField = (key, val) => {
    const container = api.createElement('div');
    container.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

    const jsonStr = JSON.stringify(val, null, 2);
    const lineCount = jsonStr.split('\n').length;
    const isLarge = lineCount > 10;

    if (isLarge) {
      const summary = api.createElement('div');
      summary.style.cssText = 'font-size: 0.75rem; color: var(--color-text-tertiary); cursor: pointer; user-select: none;';
      const keyCount = typeof val === 'object' && val !== null ? Object.keys(val).length : 0;
      summary.textContent = '(internal, ' + keyCount + ' entries, click to expand)';
      container.appendChild(summary);

      const textarea = api.createElement('textarea');
      textarea.value = jsonStr;
      textarea.style.cssText = 'display: none; width: 100%; min-height: 150px; max-height: 400px; font-family: monospace; font-size: 0.75rem; padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); resize: vertical; background: var(--color-bg-surface-alt);';
      if (!isEditable) textarea.readOnly = true;

      if (isEditable) {
        const errorEl = api.createElement('div');
        errorEl.style.cssText = 'display: none; color: var(--color-danger); font-size: 0.75rem;';
        textarea.oninput = () => {
          try {
            const parsed = JSON.parse(textarea.value);
            updateProp(key, parsed);
            errorEl.style.display = 'none';
            textarea.style.borderColor = 'var(--color-border)';
          } catch (e) {
            errorEl.textContent = 'Invalid JSON';
            errorEl.style.display = 'block';
            textarea.style.borderColor = 'var(--color-danger)';
          }
        };
        container.appendChild(errorEl);
      }

      container.appendChild(textarea);

      summary.onclick = () => {
        const isHidden = textarea.style.display === 'none';
        textarea.style.display = isHidden ? 'block' : 'none';
        summary.textContent = isHidden
          ? '(internal, ' + keyCount + ' entries, click to collapse)'
          : '(internal, ' + keyCount + ' entries, click to expand)';
      };
    } else {
      const textarea = api.createElement('textarea');
      textarea.value = jsonStr;
      textarea.style.cssText = 'width: 100%; min-height: 60px; font-family: monospace; font-size: 0.75rem; padding: 8px; border: 1px solid var(--color-border); border-radius: var(--border-radius); resize: vertical; background: var(--color-bg-surface-alt);';
      if (!isEditable) textarea.readOnly = true;

      if (isEditable) {
        const errorEl = api.createElement('div');
        errorEl.style.cssText = 'color: var(--color-danger); font-size: 0.75rem; min-height: 16px;';
        textarea.oninput = () => {
          try {
            const parsed = JSON.parse(textarea.value);
            updateProp(key, parsed);
            errorEl.textContent = '';
            textarea.style.borderColor = 'var(--color-border)';
          } catch (e) {
            errorEl.textContent = 'Invalid JSON';
            textarea.style.borderColor = 'var(--color-danger)';
          }
        };
        container.appendChild(textarea);
        container.appendChild(errorEl);
      } else {
        container.appendChild(textarea);
      }
    }

    return container;
  };

  // When a fields schema is provided, iterate over schema keys (shows all defined fields
  // even if missing from obj, and ignores unknown keys in obj). Without a schema,
  // iterate over the actual object keys with type inference.
  const keys = fields ? Object.keys(fields) : Object.keys(obj);

  for (const key of keys) {
    const val = obj[key];
    const propRow = api.createElement('div', { class: 'field-object-prop' });
    propRow.style.cssText = 'display: flex; flex-direction: column; gap: 4px;';

    const propHeader = api.createElement('div');
    propHeader.style.cssText = 'display: flex; align-items: center; gap: 8px;';

    if (fields) {
      // Schema-driven: show display label, no rename or delete controls
      const keyLabel = api.createElement('span');
      keyLabel.textContent = fields[key].label || key;
      keyLabel.style.cssText = 'font-weight: 500; font-size: 0.8125rem; color: var(--color-text-secondary);';
      propHeader.appendChild(keyLabel);
    } else if (isEditable) {
      const keyInput = api.createElement('input', { type: 'text' });
      keyInput.value = key;
      keyInput.style.cssText = 'font-weight: 500; font-size: 0.8125rem; color: var(--color-text-secondary); background: transparent; border: 1px solid transparent; border-radius: 3px; padding: 2px 4px; width: auto; min-width: 80px;';
      keyInput.onblur = () => renameProp(key, keyInput.value.trim());
      keyInput.onkeydown = (e) => { if (e.key === 'Enter') keyInput.blur(); };
      propHeader.appendChild(keyInput);

      const deleteBtn = api.createElement('button');
      deleteBtn.textContent = '×';
      deleteBtn.style.cssText = 'background: none; border: none; color: var(--color-text-tertiary); cursor: pointer; font-size: 1rem; padding: 0 4px; line-height: 1;';
      deleteBtn.onclick = async () => {
        const modalLib = await api.require('modal-lib');
        if (await modalLib.confirm({
          message: 'Delete property "' + key + '"?',
          title: 'Delete Property',
          confirmText: 'Delete',
          confirmStyle: 'danger',
          api
        })) {
          deleteProp(key);
          propRow.remove();
        }
      };
      deleteBtn.title = 'Remove property';
      propHeader.appendChild(deleteBtn);
    } else {
      const keyLabel = api.createElement('span');
      keyLabel.textContent = key;
      keyLabel.style.cssText = 'font-weight: 500; font-size: 0.8125rem; color: var(--color-text-secondary);';
      propHeader.appendChild(keyLabel);
    }

    propRow.appendChild(propHeader);

    // _ prefix treatment only applies in type-inference mode
    if (!fields && key.startsWith('_')) {
      const fieldEl = renderInternalField(key, val);
      propRow.appendChild(fieldEl);
      propsContainer.appendChild(propRow);
      continue;
    }

    let fieldEl;
    try {
      if (fields && fields[key]) {
        const spec = fields[key];
        const fieldViewName = 'field-view-' + (spec.field_view || 'json');
        const fv = await api.require(fieldViewName);
        fieldEl = await fv.render(val, {
          ...spec,
          mode,
          onChange: isEditable ? (v) => updateProp(key, v) : null,
          label: null,
        }, api);
      } else {
        const valType = Array.isArray(val) ? 'array' : typeof val;
        if (valType === 'string') {
          const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
          if (guidPattern.test(val)) {
            const fieldView = await api.require('field-view-item-ref');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else if (key === 'code') {
            const fieldView = await api.require('field-view-code-editable');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else if (val.length > 100 || val.includes('\n')) {
            const fieldView = await api.require('field-view-textarea');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else {
            const fieldView = await api.require('field-view-text');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          }
        } else if (valType === 'number') {
          const fieldView = await api.require('field-view-number');
          fieldEl = await fieldView.render(val, {
            mode,
            onChange: isEditable ? (v) => updateProp(key, v) : null
          }, api);
        } else if (valType === 'boolean') {
          const fieldView = await api.require('field-view-checkbox');
          fieldEl = await fieldView.render(val, {
            mode,
            onChange: isEditable ? (v) => updateProp(key, v) : null
          }, api);
        } else if (valType === 'object' && val !== null) {
          fieldEl = await render(val, {
            mode,
            onChange: isEditable ? (v) => updateProp(key, v) : null,
            indent: indent + 1
          }, api);
        } else if (valType === 'array') {
          const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
          if (val[0] === ':doc') {
            const fvName = mode === 'editable' ? 'field-view-doc-editable' : 'field-view-doc-readonly';
            const fieldView = await api.require(fvName);
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else if (key === 'hob') {
            const fieldView = await api.require('field-view-hob-structural');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else if (val.length > 0 && val.every(v => typeof v === 'string' && guidPattern.test(v))) {
            const fieldView = await api.require('field-view-tags');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          } else {
            const fieldView = await api.require('field-view-json');
            fieldEl = await fieldView.render(val, {
              mode,
              onChange: isEditable ? (v) => updateProp(key, v) : null
            }, api);
          }
        } else {
          const fieldView = await api.require('field-view-json');
          fieldEl = await fieldView.render(val, {
            mode,
            onChange: isEditable ? (v) => updateProp(key, v) : null
          }, api);
        }
      }
    } catch (e) {
      fieldEl = api.createElement('span');
      fieldEl.textContent = JSON.stringify(val);
      fieldEl.style.cssText = 'font-family: monospace; font-size: 0.8125rem;';
    }

    propRow.appendChild(fieldEl);
    propsContainer.appendChild(propRow);
  }

  wrapper.appendChild(propsContainer);

  if (!fields && isEditable) {
    const addRow = api.createElement('div');
    addRow.style.cssText = 'margin-top: 8px;';

    const addBtn = api.createElement('button');
    addBtn.textContent = '+ Add Property';
    addBtn.style.cssText = 'padding: 4px 12px; font-size: 0.75rem; cursor: pointer; background: var(--color-bg-surface-alt); border: 1px solid var(--color-border-light); border-radius: var(--border-radius); color: var(--color-text-secondary);';
    addBtn.onclick = () => {
      let newKey = 'newProperty';
      let i = 1;
      while (obj.hasOwnProperty(newKey)) {
        newKey = 'newProperty' + i++;
      }
      onChange({ ...obj, [newKey]: '' });
    };
    addRow.appendChild(addBtn);
    wrapper.appendChild(addRow);
  }

  if (keys.length === 0 && !isEditable) {
    const emptyEl = api.createElement('div');
    emptyEl.textContent = '(empty object)';
    emptyEl.style.cssText = 'color: var(--color-text-tertiary); font-style: italic; font-size: 0.8125rem;';
    propsContainer.appendChild(emptyEl);
  }

  return wrapper;
}
